gbd_(){return"Demandes de suppression de r\xe9servation"},
gbd0(){return"Les membres peuvent DEMANDER la suppression d'une r\xe9servation pass\xe9e ou point\xe9e ; un propri\xe9taire/admin valide. D\xe9sactiv\xe9, ces r\xe9servations ne peuvent pas \xeatre supprim\xe9es."},
gbd1(){return"L'espace de d\xe9monstration"},
