gbdj(){return"Paires d'environnements"},
gbdk(){return"Un espace et son jumeau \u2014 le c\xf4t\xe9 d\xe9veloppement et le c\xf4t\xe9 production \u2014 comme un couple : une carte dans Profils avec un interrupteur, et le jumeau cr\xe9\xe9 \xe0 la demande avec la configuration copi\xe9e. D\xe9sactiv\xe9 : deux entr\xe9es sans lien."},
