gbdy(){return"Astuces d'aide"},
gbdz(){return"Permet \xe0 une personne qui n'est pas membre de demander \xe0 visiter cet espace, et \xe0 quelqu'un qui g\xe8re les r\xe9servations de l'admettre ou de refuser. Une visite ne cr\xe9e ni adh\xe9sion, ni abonnement, ni r\xf4le. D\xe9sactiv\xe9 : personne ne demande ni n'est admis ici."},
gbdA(){return"Visites d'invit\xe9s"},
