gbdH(){return"TVA d\xe9ductible"},
gbdI(){return"Assistant d'instance"},
gbdJ(){return"Sur l'\xe9cran Serveur, un assistant cr\xe9e un nouveau projet Supabase, installe le sch\xe9ma de l'app, d\xe9ploie ses fonctions et y connecte l'appareil \u2014 un jeton d'acc\xe8s, pas de terminal. D\xe9sactiv\xe9 : les \xe9tapes manuelles seulement."},
gbdK(){return"D\xe9sactiv\xe9 : rien de nouveau ne commence ; ce qui est en cours peut encore \xeatre trait\xe9 et clos."},
